/**
 * Test Suite: Phase 71 — First real GameContent payload export
 * - integration/ payload generated by the adapter, deterministic, schema-valid
 * - Evidence fixture valid and read-only; registry still PREPARING
 */
import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';
import { createJiti } from 'jiti';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, '..');
const read = (p) => fs.readFileSync(path.join(root, p), 'utf-8');
const jiti = createJiti(import.meta.url);
const mem = new Map();
globalThis.localStorage = { getItem: (k) => mem.get(k) ?? null, setItem: (k, v) => mem.set(k, String(v)), removeItem: (k) => mem.delete(k), clear: () => mem.clear(), key: (i) => [...mem.keys()][i], get length() { return mem.size; } };
globalThis.window = globalThis.window ?? { localStorage: globalThis.localStorage, addEventListener() {}, removeEventListener() {} };

let passed = 0;
let failed = 0;
async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✅ ${name}`);
    passed++;
  } catch (err) {
    console.log(`  ❌ ${name}\n     ${err.message}`);
    failed++;
  }
}



console.log('=== Phase 71: First real GameContent payload export ===\n');
const os = await import('node:os');
const crypto = await import('node:crypto');
const { default: AjvMod } = await import(path.join(root, 'node_modules/ajv/dist/ajv.js'));
const Ajv = AjvMod.default ?? AjvMod;
const K = await jiti.import(path.join(root, 'src/content/knowledge/index.ts'));
const { CURRICULUM: C } = await jiti.import(path.join(root, 'src/curriculum/data.ts'));
const CT = await jiti.import(path.join(root, 'src/learning/games/contracts.ts'));
const EA = await jiti.import(path.join(root, 'src/learning/games/evidenceAdapter.ts'));
const RG = await jiti.import(path.join(root, 'src/learning/games/registry.ts'));
const { useStore } = await jiti.import(path.join(root, 'src/store/useStore.ts'));
const json = (p) => JSON.parse(read(p));
const PAYLOAD = 'integration/game-content/prog-ctrl-conditions.gamecontent.json';
const FIXTURE = 'integration/game-evidence/prog-ctrl-conditions.example.gameevidence.json';
const GC = json(PAYLOAD);
const EV = json(FIXTURE);
const ajv = new Ajv({ allErrors: true, strict: true });
const vContent = ajv.compile(json('integration/contracts/gamecontent-1.1.schema.json'));
const vEvidence = ajv.compile(json('integration/contracts/gameevidence-1.1.schema.json'));
const exportTo = (dir) => execFileSync('node', [path.join(root, 'scripts/export-game-content.mjs'), dir], { encoding: 'utf-8' });

await test('export is deterministic and the committed payload is exactly the adapter output (not hand-maintained)', () => {
  const a = fs.mkdtempSync(path.join(os.tmpdir(), 'v2u-gc-a-'));
  const b = fs.mkdtempSync(path.join(os.tmpdir(), 'v2u-gc-b-'));
  exportTo(a); exportTo(b);
  for (const f of ['prog-ctrl-conditions.gamecontent.json', 'manifest.json']) {
    const x = fs.readFileSync(path.join(a, f), 'utf-8');
    assert.strictEqual(x, fs.readFileSync(path.join(b, f), 'utf-8'), `${f}: two exports differ`);
    assert.strictEqual(x, read(`integration/game-content/${f}`), `${f}: committed file differs from a fresh export — run npm run export:game-content`);
  }
});

await test('exported JSON validates against GameContent 1.1 (JSON Schema + V2U validator)', () => {
  assert(vContent(GC), JSON.stringify(vContent.errors));
  assert.deepStrictEqual(CT.validateGameContent(GC), []);
  assert(!vContent({ ...GC, version: '1.0' }));
  assert(!vContent({ ...GC, extraField: 1 }), 'unknown fields rejected');
  assert(!vContent({ ...GC, readiness: 'MAYBE' }));
});

await test('manifest: sha256 matches, registry still PREPARING, no learning effects', () => {
  const m = json('integration/game-content/manifest.json');
  assert.strictEqual(m.files.length, 1);
  const f = m.files[0];
  assert.strictEqual(f.sha256, crypto.createHash('sha256').update(read(PAYLOAD)).digest('hex'));
  assert.strictEqual(f.registryStatus, 'PREPARING');
  assert.strictEqual(f.learningEffectsActive, false);
  assert.strictEqual(RG.getLessonGameAvailability('prog-ctrl-conditions'), 'PREPARING');
  for (const l of C.lessons) if (l.id !== 'prog-ctrl-conditions') assert.strictEqual(RG.getLessonGameAvailability(l.id), 'NOT_AVAILABLE');
});

await test('lesson ID, skill IDs and prerequisites are real; readiness matches the knowledge layer', () => {
  const lesson = C.lessons.find((l) => l.id === GC.lessonId);
  assert(lesson && GC.lessonId === 'prog-ctrl-conditions');
  assert.deepStrictEqual(GC.skills.map((s) => s.id), lesson.skillIds);
  assert.deepStrictEqual(GC.skills.map((s) => s.id), ['skill-prog-conditions']);
  for (const s of GC.skills) assert(C.skills.some((x) => x.id === s.id && x.title === s.title));
  assert.deepStrictEqual(GC.prerequisites.map((p) => p.lessonId), lesson.prerequisites);
  assert.strictEqual(GC.readiness, K.getLessonKnowledge(GC.lessonId).audit.readiness);
});

await test('knowledge boundary: allowed/notYet copied from the lesson; no later concepts in any code', () => {
  const k = K.getLessonKnowledge(GC.lessonId);
  assert.deepStrictEqual(GC.boundary, { allowedKnowledge: k.allowedKnowledge, notYetAllowed: k.notYetAllowed });
  const code = [...GC.teaching.predictions.map((p) => p.code), ...GC.teaching.starterCode.map((s) => s.code), ...GC.teaching.debugging.flatMap((d) => [d.brokenCode, d.fixedCode])];
  assert(code.length >= 12);
  for (const c of code) {
    assert(!/\b(for|while|def|class|import|from|try|except|match|case|lambda|return|yield)\b/.test(c), `later concept in: ${c}`);
    assert(!/[[\]{}]/.test(c), `list/dict in: ${c}`);
    assert(!/\S+ if .+ else /.test(c), `one-line conditional in: ${c}`);
  }
  const allText = JSON.stringify(GC.teaching);
  for (const n of ['การวนซ้ำ', 'try / except', 'match / case']) assert(!allText.includes(n), n);
});

await test('no duplicated curriculum: the game layer source holds no lesson text; only the generated JSON does', () => {
  const k = K.getLessonKnowledge(GC.lessonId);
  const samples = [k.summary[0], k.mistakes[0].mistake, k.workedExamples[0].problem, k.guided[0].explanation, k.allowedKnowledge[0]];
  const gameSrc = fs.readdirSync(path.join(root, 'src/learning/games')).map((f) => read(`src/learning/games/${f}`)).join('\n') + read('scripts/export-game-content.mjs');
  for (const s of samples) assert(!gameSrc.includes(s), `hand-copied lesson text found: ${s}`);
  for (const s of samples) assert(read(PAYLOAD).includes(JSON.stringify(s).slice(1, -1)), `payload should carry: ${s}`);
});

await test('evidence fixture validates (schema + validator) and references the real lesson and skill', () => {
  assert(vEvidence(EV), JSON.stringify(vEvidence.errors));
  assert.deepStrictEqual(CT.validateGameEvidence(EV), []);
  assert.strictEqual(EV.lessonId, 'prog-ctrl-conditions');
  assert.deepStrictEqual(EV.skillEvidence.map((s) => s.skillId), ['skill-prog-conditions']);
  for (const f of CT.FORBIDDEN_EVIDENCE_FIELDS) assert(!vEvidence({ ...EV, [f]: 1 }), `schema rejects ${f}`);
});

await test('evidence interpretation mutates no V2U state (store + storage unchanged, effects all false)', () => {
  const snap = () => JSON.stringify(useStore.getState(), (k2, v) => (typeof v === 'function' ? undefined : v));
  const before = snap();
  const ls = JSON.stringify({ ...mem });
  const r = EA.interpretGameEvidence(Object.freeze(structuredClone(EV)));
  assert(r.accepted, r.problems.join());
  assert.deepStrictEqual(r.effects, { mastery: false, skillStatus: false, review: false, nextStep: false, diagnostic: false });
  assert.strictEqual(r.learningEffectsActive, false);
  assert.strictEqual(snap(), before);
  assert.strictEqual(JSON.stringify({ ...mem }), ls);
});

await test('contract docs cover every field of both schemas', () => {
  const doc = read('integration/contracts/README.md');
  const walk = (s, out = new Set()) => { for (const [k2, v] of Object.entries(s.properties ?? {})) { out.add(k2); walk(v, out); if (v.items) walk(v.items, out); } return out; };
  for (const sch of ['gamecontent-1.1.schema.json', 'gameevidence-1.1.schema.json']) for (const f of walk(json(`integration/contracts/${sch}`))) assert(doc.includes(f), `README misses ${f}`);
});

console.log(`\nTotal: ${passed + failed} | Passed: ${passed} | Failed: ${failed}`);
if (failed > 0) process.exit(1);
